# ================================================================ part 2
opener(2, 'חוזה אקדמה וחוזה עתידי', 'שאלת החלק: מה קורה כששני הצדדים מחויבים?',
       ['חוזה אקדמה (Forward): סיפור, טבלה ותרשים', 'קונה (Long) ומוכר (Short): סכום אפס', 'חוזה עתידי (Futures): מה שונה', 'אקסל: התזרים לכל צד'], 30)

S('s-longshort', 'חוזה אקדמה: הסיפור', 'חוזה אקדמה (Forward): סיפור על חבית נפט',
  '<div class="row eq2 top"><div class="rl">'
  + RL(['<b>היום.</b> חבית נפט עולה 100 דולר. מיכל צריכה חבית בעוד חצי שנה. רון מחזיק חבית, וימכור אותה בעוד חצי שנה.',
        '<b>ההסכם.</b> הם חותמים היום: בעוד חצי שנה מיכל תקנה מרון חבית נפט ב-100 דולר, יהיה מחיר השוק אשר יהיה.',
        '<b>כסף היום:</b> אפס. שום חבית לא זזה. יש רק חוזה.',
        '<b>בעוד חצי שנה, החבית ב-110 דולר.</b> מיכל קונה ב-100 מה ששווה 110: היא הרוויחה 10. רון מוכר ב-100 מה ששווה 110: הוא הפסיד 10.']) + '</div><div class="col">'
  + DEF('חוזה אקדמה (Forward contract)', 'הסכם היום על קנייה או מכירה בעתיד, במחיר שנקבע היום. שני הצדדים מחויבים.', 'מחיר החוזה נקרא $K$: כאן, $K = 100$ דולר לחבית.', 5, trm='forward')
  + '<div class="row eq2 top">' + DEF('פוזיציה ארוכה (Long)', 'הצד הקונה.', 'מיכל.', 6, trm='long', cls='mini') + DEF('פוזיציה קצרה (Short)', 'הצד המוכר.', 'רון.', 6, trm='short', cls='mini') + '</div></div></div>'
  + TOON('hands', 'לוחצים יד היום. נפגשים בעוד חצי שנה. בלי צ׳ק.', 7), kick='חלק 2 · סיפור')

_t, _n = GT(['המחיר בפקיעה ($S_{T}$)', 'תזרים ל-Long, מיכל', 'תזרים ל-Short, רון', 'סך שני הצדדים'], [
    ['90', ('$-10$', 'קונה ב-100 מה ששווה 90: $90 − 100$'), ('10', 'מוכר ב-100 מה ששווה 90: $100 − 90$'), ('0', '$−10 + 10$')],
    ['100', ('0', '$100 − 100$'), ('0', '$100 − 100$'), ('0', '$0 + 0$')],
    ['110', ('10', '$110 − 100$'), ('$-10$', '$100 − 110$'), ('0', '$10 − 10$')]])
S('s-fwdtbl', 'תרגיל בסיסי: התזרים לכל צד', 'תרגיל בסיסי: מה התזרים לכל צד?',
  '<div class="card qstem"><p>' + TX('שני צדדים מתקשרים בחוזה אקדמה (Forward) על חבית נפט. מחיר החוזה (K) הוא 100 דולר. מה יהיה התזרים לכל צד אם המחיר בפקיעה יהיה 90, 100 או 110 דולר?') + '</p></div>' + _t
  + ST(_n, '<div class="row eq2 top" style="margin-top:10px"><div class="card tnote">' + TX('<b>Long:</b> התזרים הוא $S_{T} − K$. <b>Short:</b> התזרים הוא $K − S_{T}$.') + '</div><div class="card tnote">' + TX('<b>$S_{T}$:</b> המחיר בפקיעה. <b>K:</b> מחיר החוזה. <b>סכום אפס (Zero sum):</b> הרווח של האחד הוא הפסד השני.') + '</div></div>'), kick='חלק 2 · תרגיל מודרך')

S('s-fwdfut', 'Forward מול Futures', 'חוזה אקדמה (Forward) מול חוזה עתידי (Futures)',
  DEF('חוזה עתידי (Futures contract)', 'אותו רעיון: מחיר עתידי שנקבע היום. אלא שהחוזה סטנדרטי ונסחר בבורסה.', 'חוזה על נפט WTI מתייחס ל-1,000 חביות. המחיר עלה בדולר ביום נתון: הקונה מקבל באותו יום 1,000 דולר.', trm='futures')
  + ST(1, TABLE(['מאפיין', 'חוזה אקדמה (Forward)', 'חוזה עתידי (Futures)'], [
      ['היכן', 'ישירות מול הצד השני, מעבר לדלפק (OTC)', 'בבורסה (Exchange)'],
      ['תנאים', 'מותאמים לצדדים', 'אחידים: כמות, מועד, איכות'],
      ['הסיכון שהצד השני לא ישלם', 'קיים', 'מצומצם: המסלקה (Clearing house) ערבה'],
      ['התחשבנות', 'בפקיעה', 'בכל יום, דרך חשבון ביטחונות (Margin)']]))
  + BAND('note', 'התזרים המצטבר דומה בשני החוזים. המנגנון שונה, ונפרט אותו בשיעור 2.', 2), kick='חלק 2 · השוואה')

S('s-forward', 'חוזה אקדמה: הצגה גרפית', 'חוזה אקדמה (Forward): הצגה גרפית',
  STEPS(CHART([dict(pts=POS(1, 'fwd', 100, 0, 70, 130), c='#0f9d90', lab='Long', labat=(125, 25), laby=-6, s=7), dict(pts=POS(-1, 'fwd', 100, 0, 70, 130), c='#ff6a4d', lab='Short', labat=(125, -25), laby=20, s=8)], 70, 130, -40, 40, [70, 80, 90, 100, 110, 120, 130], [-40, -20, 0, 20, 40], H=410, xl='מחיר החבית בפקיעה, S_T (דולר)', yl='תזרים (Payoff)', xs=2, ys=3,
              marks=[dict(x=90, y=-10, t='−10', dy=22, s=4, c='#0f9d90'), dict(x=100, y=0, t='0', dy=-12, s=5, c='#0f9d90'), dict(x=110, y=10, t='10', dy=-12, s=6, c='#0f9d90')]),
        RL(['<b>הנתון:</b> מחיר החוזה, $K$, הוא <b>100 דולר לחבית</b>. זה המחיר שבו Long יקנה ו-Short ימכור בפקיעה, יהיה מחיר השוק אשר יהיה.', '<b>ציר אופקי:</b> המחיר בפקיעה, $S_{T}$. ככל שנלך ימינה בתרשים, החבית יקרה יותר.', '<b>ציר אנכי:</b> התזרים (Payoff). הקו הכהה הוא נקודת האפס. מעליו רווח, מתחתיו הפסד.', '<b>Long, מחיר 90:</b> $90 − 100 = −10$.', '<b>Long, מחיר 100:</b> $100 − 100 = 0$. הקו חוצה את האפס ב-$K = 100$.', '<b>Long, מחיר 110:</b> $110 − 100 = 10$.', '<b>מחברים:</b> קו ישר ועולה. כל דולר מעל $K$ הוא דולר רווח.', '<b>Short:</b> אותו קו בדיוק, הפוך. תמונת ראי ביחס לאפס.'])), kick='חלק 2 · תרשים')

_d = {'A1': 'מחיר החוזה (K)', 'B1': 100, 'A3': 'מחיר בפקיעה', 'B3': 'Long', 'C3': 'Short', 'D3': 'סך הכול'}
_s = {}
for i, p in enumerate([80, 90, 100, 110, 120]):
    r = 4 + i; _d[f'A{r}'] = p; _s[f'B{r}'] = f'=A{r}-$B$1'; _s[f'C{r}'] = f'=$B$1-A{r}'; _s[f'D{r}'] = f'=B{r}+C{r}'
XLS('x-fwd', 'אקסל: חוזה אקדמה', 'אקסל: חוזה אקדמה (Forward) על חבית נפט',
    'מיכל קונה (Long) ורון מוכר (Short) חוזה אקדמה (Forward) על חבית נפט אחת, במחיר חוזה (K) של 100 דולר. <b>נדרש:</b> לכל מחיר אפשרי של החבית בפקיעה, הציגו את התזרים של מיכל, את התזרים של רון ואת הסכום של שניהם. כאן מותר להקליד מספרים או נוסחאות, והתרשים נבנה מהתאים שלכם.',
    _d, _s, [160, 90, 90, 90], [3], hints=['Long קונה ב-K: מחיר בפקיעה פחות K.', 'Short מוכר ב-K: הסימן הפוך.'], remind='<b>תזרים לקונה (Long)</b> = $S_{T} − K$.<br><b>תזרים למוכר (Short)</b> = $K − S_{T}$.<br><b>סך הכול</b> = Long + Short.', partial=['B4', 'C4', 'D4'], values=True,
    chart=CH(['A4', 'A8'], [dict(y=['B4', 'B8'], c='#0f9d90', lab='Long'), dict(y=['C4', 'C8'], c='#ff6a4d', lab='Short', dy=22)], 80, 120, -20, 20, [80, 90, 100, 110, 120], [-20, -10, 0, 10, 20], yl='דולר'))

